css:
body { 
font-family: 'Times New Roman', Times, serif; 
font-size: 10pt; 
}
.voucher-container { width: 100%; margin: 0 auto; border: 1px solid #000; padding: 15px; }
.header-section { text-align: center; margin-bottom: 10px; }
.header-section h3 { margin: 5px 0; }
.header-section small { display: block; margin-top: -5px; }

.header-info-table {
width: 100%; 
border-collapse: collapse;
margin-bottom: 0px; 
}
.header-info-table td { 
border: 1px solid #000; 
padding: 5px; 
vertical-align: top; 
}

.info-table { 
width: 100%; 
border-collapse: collapse; 
margin-top: -1px; 
margin-bottom: 0px; 
}


.details-table { 
width: 100%; 
border-collapse: collapse; 
margin-top: -1px; 
margin-bottom: 15px; 
}


.info-table .main-row td {

border: none;
border-bottom: 1px solid #000; 
}
.info-table .main-row td:first-child {
border-left: 1px solid #000;
}
.info-table .main-row td:last-child {
border-right: 1px solid #000;
}
.info-field-group {
padding: 2px 0;
line-height: 1.8;
}

.details-table th, .details-table td { border: 1px solid #000; padding: 5px; vertical-align: top; }
.details-table th { background-color: #f2f2f2; text-align: center; font-weight: bold; }
.details-table td { font-size: 9pt; }
.footer-section { margin-top: 20px; }
.left-align { text-align: left; }
.right-align { text-align: right; }
.no-border { border: none !important; }
